float
__cosf ( float x )
{
float	absx;
double	dx, xsq, poly;
double	dn;
int	n;
double	result;
int	ix, xpt;


	ix = *(int *)&x;
	xpt = (ix >> 22);
	xpt &= 0x1ff;




	if ( xpt < 0x136 )
	{






		absx = (( x ) > 0) ? ( x ) : -( x ) ;

		dx = absx;

		dn = dx*rpi.d + 0.5;
		n = (int)((( dn ) >= 0.0) ? (( dn ) + 0.5) : (( dn ) - 0.5)) ;
		dn = n;

		dn -= 0.5;

		dx = dx - dn*pihi.d;
		dx = dx - dn*pilo.d;	 

		xsq = dx*dx;

		poly = ((P[4].d*xsq + P[3].d)*xsq + P[2].d)*xsq + P[1].d;

		result = dx + (dx*xsq)*poly;



		if ( (n & 1) == 0 )
			return ( (float)result );

		return ( -(float)result );
	}

	if ( x != x )
	{




		return ( D_8004AA00 );
	}



	return ( zero.f );
}

