extern s32 D_800470B8;



s32 osAiSetFrequency(u32 frequency) {
    register unsigned int dacRate;
    register unsigned char bitRate;
    register float f;



    f = D_800470B8 / (float)frequency + .5f;
    dacRate = f;

    if (dacRate < 132 ) {
        return -1;
    }

    bitRate = dacRate / 66;

    if (bitRate > 16 ) {
        bitRate = 16 ;
    }

    (*(vu32*)((u32)(  (0x04500000  + 0x10)   )|0xA0000000) =(u32)(  dacRate - 1 )) ;
    (*(vu32*)((u32)(  (0x04500000  + 0x14)   )|0xA0000000) =(u32)(  bitRate - 1 )) ;

    (*(vu32*)((u32)(  (0x04500000  + 0x08)   )|0xA0000000) =(u32)(  1  )) ;

    return D_800470B8 / (s32)dacRate;
}

